for filename, text in translations.items():
    match = re.match(r'^(.*?)_(para|title)(?:_(\d+))?\.json$', filename)
    if not match: continue
    slug = match.group(1)
    typ = match.group(2)
    
    out_data = {
        "slug": slug,
        "type": typ,
        "uk_text": text
    }
    if typ == "para":
        out_data["index"] = int(match.group(3))
        
    out_path = os.path.join(result_dir, filename)
    with open(out_path, 'w', encoding='utf-8') as f:
        json.dump(out_data, f, ensure_ascii=False, indent=2)

